sys_script_include.script:
var IncidentsForUserWithout = Class.create();
IncidentsForUserWithout.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
  getRecentIncidents: function () {
    var userId = gs.getUserID();

    var gr = new GlideRecord("incident");
    gr.addQuery("caller_id", userId);
    gr.orderByDesc("sys_updated_on");
    gr.setLimit(10);
    gr.query();

    var out = [];
    while (gr.next()) {
      out.push({
        number: gr.getValue("number"),
        short_description: gr.getValue("short_description"),
        state: gr.getDisplayValue("state"),
        sys_updated_on: gr.getDisplayValue("sys_updated_on")
      });
    }
    return new global.JSON().encode(out);
  },
  type: "IncidentsForUserWithout"
});
